# Use horizontal neighbor rule on test input - this was my best performing rule
def apply_horizontal_neighbor_rule(grid):
    """Change if cell has a horizontal FG neighbor (left or right)"""
    result = [[grid[r][c] for c in range(len(grid[0]))] for r in range(len(grid))]
    bg = 8

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != bg:
                # Check left or right neighbor
                has_h_neighbor = False
                if c > 0 and grid[r][c-1] == grid[r][c]:
                    has_h_neighbor = True
                if c < len(grid[0])-1 and grid[r][c+1] == grid[r][c]:
                    has_h_neighbor = True

                if has_h_neighbor:
                    result[r][c] = 2
    return result

